insert into topic_contents (topic_id, summary, content_md, example_question) values ('9683464a-e0ce-493b-ae60-58c924e2ae5c', 'Bu konu; ''de/da'' bağlacı ile hâl eki, ''ki'' bağlacı ile ''-ki'' eki, ''mi'' soru eki ve büyük harf kullanımı gibi en sık karıştırılan yazım kurallarını örneklerle ele alır.', '## ''de/da'' Bağlacı ve Hâl Eki
insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('4fae2e1f-eb50-46df-a94c-90b4fc97acfe', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'kolay'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde ''de'' bağlaç olarak kullanılmış, bu nedenle ayrı yazılmıştır?', 'Bağlaç olan ''de/da'' ile hâl eki olan ''-de/-da''yı ayırt eder.', 'İkinci cümledeki ''da'', ''O bizimle gelmek istedi.'' cümlesinden çıkarıldığında anlam bütünlüğü bozulmadığı için bağlaçtır ve ayrı yazılır. Diğer cümlelerdeki ''-de'' ekleri isme bulunma hâli katan bir ek olduğu için bitişik yazılmıştır.');
