insert into questions (id, topic_id, difficulty, question_text, kazanim, explanation) values ('70a7a661-b3e9-4c6e-9908-3d6d210de2bc', '9683464a-e0ce-493b-ae60-58c924e2ae5c', 'zor'::difficulty_level, 'Aşağıdaki cümlelerin hangisinde bir yazım yanlışı yoktur?', 'Birden fazla yazım kuralını bir arada değerlendirerek doğru cümleyi belirler.', 'İkinci cümlede bağlaç olan ''de'' doğru biçimde ayrı, soru eki ''mi'' de kurala uygun olarak ayrı yazılmıştır. Diğer cümlelerde sırasıyla ''kitapta'' yerine ''kitapda'', ''yarınki'' yerine ''yarın ki'' ve ''onunki'' yerine ''onun ki'' kullanılarak yazım yanlışı yapılmıştır.');
